"""Ф6-П2: общая библиотека — поиск статьи тома по титулу/году, классификация печатных строк статьи (титры/справки vs проза)."""
import json, re, functools, difflib
CRED = re.compile(r'^(?:[^А-ЯЁа-яёA-Za-z0-9]{0,6})(Ав[тг][.,]?\s?-?\s?(сц|си|сп|рук|текст|и реж)|Авт\.? ?сцен|Ат сцеп|Апт\. сцеп|Двт\. сцен|Act\. сцен|Авт\. текст|Автор[ы]? (сцен|сцеп|и реж|новой|-рук)|Сцен[.,]|Пом\. (реж|опер)|Сореж|Реж[.,] и|Реж и |Реж\.-|Опер и |Авторы не установлены|Реж\.|Реж [А-ЯЁ]\.|Реж дубл|В ролях|В роли|В главных ролях|Роли (дублир|озвучив|исполн|дубл)|Опер\.|Опер [А-ЯЁ]\.|Худ\.|Худ [А-ЯЁ]\.|Худож\.|Художник|Художественный руководитель|Композ|Звукоопер|Монтаж\.|Монтаж [А-ЯЁ]|Ассист|Костюм\.|Грим\.|Ред\.|Дир\. картины|Комб\. съемк|Симфонический|Государственн(ый|ая) (симфонический|академический|оркестр|хор|ансамбль|заслуженный|русский|эстрадный|камерный|духовой|народный|Большой|республиканск)|Оркестр|Вокальн|Песн[июя] исполня|Песни (в исполнении|поет|поют)|Фильм дублирован|Фильм озвучен|Библиография|Библи\.ография|Текст чита|Русский текст чита|Перевод чита|Тех\. ассист|2-й реж|2-й опер|Гл\. ред|Гл\. реж|Гл\. опер|Гл\. худ|Гл\. консульт|Кукловод|Дирижер|Хор (и|им\.|[А-ЯЁ])|Хор,|Ансамбл|Исп\. |Исполнит|Консульт|Научн\. консульт|Научный консульт|Воен\. консульт|Военн(ый|о-технич|о-морск)[а-я]* консульт|Лит\. обраб|Лит\. консульт|Запись музыки|Мультипл\.|Мультипликатор|Мультипл-|Постановщик (танц|трюк|гимнаст|боев)|Балетмейстер|Пост\. танц|Звукооформ|Ассистенты|Куклы (и декор|изготов|выполн)|Солист[ыа]?[: ]|Партии (исполня|поют)|Дублирован|Дублировали|Дублируют|Дрессировщик|Исполнители|Дубл\.|Актеры-кукловоды|Над фильмом (также )?работали|Над выпуском работали|Съемочная группа благодарит|Съемочный коллектив благодарит|Киногруппа благодарит|Киносъемочная группа благодарит|Студия благодарит|Группа каскадеров|Каскадеры|Каскадер |Трюки|Автотрюки|В съемках? (фильма |картины )?(принимал|принимают|участв|снимал|использов)|В съемке принимал|В массовых съемках|В воздушных съемках|В работе (над фильмом )?принимал|В работе над фильмом (также )?участв|В создании (фильма|картины|сборника) (принимал|также)|В (фильме|картине) (принимал|принимают|снимал|снимаются|использован|звучит|звучат|участвуют)|В концерте участвовали|В фильме-концерте участвуют|При участии|Использованы? (стихи|фрагменты|музыка|мелодии|песни|кадры)|Музыка (ансамбля|в исполнении)|Эстрадно-симфонический|Эстрадный оркестр|Духовой оркестр|Джаз|Камерный оркестр|Академический|Большой симфонический|Ленинградский (государственный|академический|камерный|симфонический|оркестр|хор|мюзик|ансамбль|театр|цирк)|Московский (государственный|академический|камерный|симфонический|оркестр|хор|мюзик|ансамбль|театр|цирк)|Таллинский (камерный|оркестр|хор)|Народн(ый|ые) (хор|песни)|Русский народный|Цыганские песни|Грузинские народные|Романсы|Хореограф|Руководитель (индийской|конно|полетов|каскад)|Рок-группа|Вокально-инструментальн|Инструментальн(ый|ая) (ансамбль|группа)|Адм\. группа|Муз\. ред|Пиротехник|Фехтовани|Мастер по свету|Мастер-светотехник|Цветоустанов|Худ\.-фотограф|Инженер|Автор, и худ\. рук|Ред\. сб|Главные роли дублировали|Соло на|Играет (на|ансамбль|оркестр)|Исполнение и запись|Клоуны|Балет (Большого|Софийск|Ленинградск|Московск|Государственн|Киевск|Пермск|Новосибирск|Академическ|театра|и хор|, хор)|Реж\.-пост|Опер\.-пост|Худ\.-пост|Пост\. |Творческая мастерская|От автора|Блок дир)', re.I)
VERB = re.compile(r'\b(мечта|решает|решил|приезжа|отправля|живет|работает|узна|приглашают|становится|получил|любит|попада|встреча|происходит|оказыва|начина|поступа|хочет|уезжа|возвраща|пытает|влюбл|погиба|убива|находит|ищет|ведет|идет|едет|рассказыва|случа)', re.I)
ENS = re.compile(r'^(Ансамбл|Оркестр|Хор|Балет|Капелл|Квартет|Трио|Группа|Солист|Дирижер)', re.I)
IDX = re.compile(r'—\s*\d{2,4}\s*$')
UPRUN = re.compile(r'[А-ЯЁ][А-ЯЁ0-9\s\-—,!?«»:;()№.…\'’]{2,}')
PRIZE = re.compile(r'^(?:[^А-ЯЁа-яё0-9]{0,4})(«[^»]{2,40}»\s*[—-]\s*(приз|премия|Главн|специальн|награда)|На ([IVX0-9]|Всесоюзн|Международн|Всемирн|Московск|Республиканск|фестивал|кинофестивал|смотре|конкурсе|[А-Я][а-я]+ (Всесоюзн|Международн|кинофестивал|фестивал))|Фильм(у)? (удостоен|присужден|награжд|отмечен|получил|был удостоен)|Государственн(ая|ой) преми|Почетн(ый|ого|ая) (диплом|грамот)|(Перв|Втор|Треть)(ая|ой) преми|Приз |Призы |Премия|Премии|Диплом|Ленинск(ая|ой) преми|Главный приз|Специальн(ый|ая) (приз|преми)|Большой приз|Золот(ая|ой|ые) (медаль|приз|медали)|Серебрян|Бронзов|В \d{4} г(оду|\.) (фильму|картине|на [IVX\d]|на [А-Я][а-я]+ (кино)?фестивал|Государственн|Ленинск|за )|Лауреат|Удостоен|Картин(а|е) (удостоен|присужден|награжд|отмечен))', re.I)
def norm_sp(s):
    s = (s or '').lower().replace('ё', 'е')
    return re.sub(r'[^а-яa-z0-9]+', ' ', s).strip()
_TR = str.maketrans({'0': 'о', '3': 'з', 'i': '1', 'l': '1', 'a': 'а', 'e': 'е', 'o': 'о', 'p': 'р', 'c': 'с', 'x': 'х', 'y': 'у', 'k': 'к', 'h': 'н', 'b': 'в', 'm': 'м', 't': 'т', 'й': 'и'})
def norm_m(s):
    """нормализация для сопоставления голов: OCR-подмены латиницы/цифр, без пробелов"""
    s = (s or '').lower().replace('ё', 'е').translate(_TR)
    return re.sub(r'[^а-я0-9]+', '', s)
@functools.lru_cache(None)
def lines(vol):
    return json.load(open(f'work/{vol}_lines.json', encoding='utf-8'))
@functools.lru_cache(None)
def heads(vol):
    """индексы головоподобных строк тома (≥3 заглавных в первых 45 знаках, не строка указателя/титров) + нормализованная строка без пробелов"""
    out = []
    for j, (n, t, p) in enumerate(lines(vol)):
        if IDX.search(t): continue
        capsok = re.match(r'^[^А-ЯЁа-яё]{0,16}(?:\d{1,4}\s*[.\-—]?\s*)?(?:[А-ЯЁ]{3,}|[А-ЯЁ]{1,2}[\s\-—,!?]+[А-ЯЁ]{2,}|[А-ЯЁ](?:\s[А-ЯЁ])+\s[А-ЯЁ]{2,}|[А-ЯЁ]{2}[.!?])', t) is not None
        metr = (re.search(r'\d+\s?ч\.?,|мтр\. неизв|\d+ м,|\d+ л,', t[:160]) is not None and not CRED.match(t)
                and re.match(r'^[^а-яё]{0,20}[А-ЯЁа-яё][^.]{0,70}[.,\-—]\s*(Экраниз|Драма|Комедия|Кинокомедия|Приключ|Кинопов|Графич|Объемн|Кукольн|Мелодрама|Детск|Агитфильм|Сатир|Ист|Муз|Фильм-|Кино|Детектив|Сборник|Комб|Культурфильм|Киноконцерт|Всесоюзный|Лирич|Героич|Военн|Биограф|Фантаст|Психологич|Социальн|Публицист|Трагед|Эксцентр|Революц|Романтич|Эпопея|Притча|Сказка|Новелл|Хроник|Спортивн|Научно|Телефильм|Водевиль|Оперетта|Балет|Опера|Концерт|Мультипл|Рисован|Документ|Художеств|Политич|Семейн|Бытов|Школьн|Историко|Юношеск|Молодежн|Производств|Драматич|Легенда|Памфлет|Пародия|Поэма|Феерия|Фарс|Гротеск|Баллада|Экранная|Историч|Киножурнал|Детский юмор|Ералаш|Цирков|Эстрадн|Обозрени|Киноальманах|Альманах|Киносборник|Сюита|Ревю|Фильм-концерт|Фильм-спектакль|Кинорассказ|Киноплакат|Киноочерк|Кинофельетон|Кинопоэма|Киноэтюд|Киношутка|Кинодрама|Киноновелл|Киносказка|Кинооперетта|Кинообозрение|Кинобаллада|Кинороман|Кинопритча|Кинопамфлет)', t) is not None)
        if not capsok and not metr: continue
        if re.match(r'^[^А-ЯЁа-яё]{0,16}(?:ВЭ|РУ|ВРЭ)\b', t): continue
        if re.match(r'^\s*(Библиограф|БИБЛИОГРАФ|ПРИЛОЖЕНИЕ|УКАЗАТЕЛЬ|СОДЕРЖАНИЕ|В ролях|В роли|Роли )', t): continue
        if CRED.match(t) and not re.match(r'^[^а-яё]{0,12}[А-ЯЁ][А-ЯЁ\s\-—,!?«»:;()№.…]{5,}', t): continue
        out.append((j, norm_m(t[:100])))
    return out
@functools.lru_cache(None)
def headset(vol):
    return {h[0] for h in heads(vol)}
def find_article(vol, title, year=None, fuzzy=True):
    """→ (idx_head, idx_end_exclusive, candidates) или None; поиск головы по нормализованному титулу без пробелов"""
    L = lines(vol)
    base = re.sub(r'\s*\(«.*$', '', title).strip()
    base2 = re.sub(r'\s*\([^)]*\)\s*$', '', base).strip()
    nt = norm_m(base2 or base)
    if len(nt) < 2: return None
    cands = [j for j, s in heads(vol) if s.startswith(nt) or (0 <= s.find(nt) <= 20)]
    if not cands and fuzzy:
        best = []
        for j, s in heads(vol):
            for off in (0, 2, 4, 6, 8, 10, 14):
                r = difflib.SequenceMatcher(None, s[off:off + len(nt)], nt).ratio()
                if r >= 0.8: best.append((r, j)); break
        cands = [j for r, j in sorted(best, reverse=True)]
    if not cands: return None
    if len(cands) > 1 and year:
        ys = [j for j in cands if str(year) in L[j][1] or (j + 1 < len(L) and str(year) in L[j + 1][1][:150])]
        if ys: cands = ys
    h = cands[0]
    hs = headset(vol)
    e = h + 1
    while e < len(L) and e not in hs:
        e += 1
    return (h, e, cands)
def block(vol, h, e):
    return [(x[0], x[1]) for x in lines(vol)[h:e]]
CASTLIKE = re.compile(r'[А-ЯЁ]\.\s?[А-ЯЁ][а-яё\-]+\s?\([^)]{1,60}\)')
INITS = re.compile(r'(?:^|[\s,;(])[А-ЯЁ]\.\s?[А-ЯЁ][а-яё\-]{2,}')
def kind(t, concert=False):
    s = t.strip()
    if not s or re.match(r'^\s*\d{1,4}\s*$', s) or re.match(r'^\d+ Заказ', s) or len(s) < 3 or re.match(r'^[^А-ЯЁа-яё0-9]+$', s): return 'junk'
    ns = norm_sp(s).replace(' ', '')
    if ns.startswith('библиограф') or difflib.SequenceMatcher(None, ns[:12], 'библиография').ratio() >= 0.8 or re.match(r'^\s*(Библиография|БИБЛИОГРАФИЯ|Библи\.ография)', s): return 'bib'
    if re.match(r'^\s*(\d-я|[IVX]+) (серия|сер\.)\s*[.—-]?\s*$', s): return 'junk'
    if CRED.match(s):
        if concert and ENS.match(s) and (len(s) > 160 or VERB.search(s)): return 'prose'
        if re.match(r'^(?:[^А-ЯЁа-яё]{0,4})В (фильме|картине) использован[ыа]? (сюжет|мотив|сказк|материал[ы]? (пьес|роман|повест|рассказ))', s): return 'prose'
        return 'cred'
    if re.match(r'^[^А-ЯЁа-яё]{0,4}[А-ЯЁ][а-яё\-]+ (оркестр|ансамбль|хор|капелла)\b', s) and len(s) < 140 and not VERB.search(s): return 'cred'
    # список ролей/имён без маркера (обрывок «В ролях»): ≥3 конструкций «И. Фамилия (роль)» или ≥5 «И. Фамилия» при отсутствии глаголов
    nc = len(CASTLIKE.findall(s))
    if nc >= 3 or (len(INITS.findall(s)) >= 5 and not VERB.search(s)) or re.match(r'^[^А-ЯЁа-яё]{0,3}[а-яё][^.]{0,40}\),\s*[А-ЯЁ]\.', s): return 'cred'
    if nc >= 2 and not VERB.search(s) and (re.search(r'\),\s*[А-ЯЁ]\.', s[:60]) or s.rstrip().endswith(').')): return 'cred'
    if PRIZE.match(s): return 'prize'
    return 'prose'
